function _mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;}}
const rng=_mulberry32(42);
const NRED=30, NBLUE=30, NL=7, NPT=NRED+NBLUE, SPACING=1.2, HALF=1.5, NSTAGE=4;
const planeY=l=>l*SPACING;

// ---------- data: pos[stage][layer][pointIdx] = Vector3 ----------
const pos=[];
for(let s=0;s<NSTAGE;s++){pos.push([]);for(let l=0;l<NL;l++){pos[s].push([]);}}
for(let i=0;i<NPT;i++){
  const red=i<NRED;
  const bx=(rng()*2-1), bz=(rng()*2-1);
  const fan=rng();                       // per-point fan factor for blue spread
  for(let l=0;l<NL;l++){
    for(let s=0;s<NSTAGE;s++){
      const w=s/3, f=l/(NL-1), e=w*f;    // training × layer effect
      let x,z;
      if(red){
        const k=1-0.88*e;
        x=bx*0.45*k; z=bz*0.45*k;
      }else{
        // wide outward fan in +X growing with height and training; bows past plane edge
        x=bx*(0.45+0.7*e)+e*(0.5+2.0*fan)*l/(NL-1)*1.4;
        z=bz*(0.45+1.1*e);
      }
      x+=(rng()-0.5)*0.05; z+=(rng()-0.5)*0.05;
      pos[s][l][i]=new THREE.Vector3(x,planeY(l),z);
    }
  }
}

// ---------- planes (clean diamond outlines, no diagonals) ----------
const corner=[[-HALF,-HALF],[HALF,-HALF],[HALF,HALF],[-HALF,HALF]];
const planeEdgeMats=[];
for(let l=0;l<NL;l++){
  const g=new THREE.Group(); g.position.y=planeY(l);
  const edgePts=corner.map(([x,z])=>new THREE.Vector3(x,0,z));
  const edgeMat=new THREE.LineBasicMaterial({color:0x333333,transparent:true,opacity:0.95});
  g.add(new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(edgePts),edgeMat));
  scene.add(g);
  planeEdgeMats.push(edgeMat);
}

// ---------- dashed prisms between consecutive planes ----------
const prismMats=[];
for(let l=0;l<NL-1;l++){
  const pm=new THREE.LineDashedMaterial({color:0xaaaaaa,dashSize:0.09,gapSize:0.07,transparent:true,opacity:0.4});
  for(let k=0;k<4;k++){
    const a=new THREE.Vector3(corner[k][0],planeY(l),corner[k][1]);
    const b=new THREE.Vector3(corner[k][0],planeY(l+1),corner[k][1]);
    const ln=new THREE.Line(new THREE.BufferGeometry().setFromPoints([a,b]),pm);
    ln.computeLineDistances(); scene.add(ln);
  }
  prismMats.push(pm);
}

// ---------- point markers ----------
const markers=[], markerMats=[];
for(let i=0;i<NPT;i++){
  const red=i<NRED;
  const mat=new THREE.MeshBasicMaterial({color:red?0xe0251b:0x2440e0,transparent:true,opacity:0.95});
  markerMats.push(mat);
  markers.push([]);
  for(let l=0;l<NL;l++){
    const m=new THREE.Mesh(new THREE.SphereGeometry(0.04,8,8),mat);
    m.userData.pointId=i;
    m.position.copy(pos[0][l][i]);
    scene.add(m); markers[i].push(m);
  }
}

// ---------- ghost clouds of the non-active stages ----------
const ghostGroups=[];
for(let s=0;s<NSTAGE;s++){
  const gg=new THREE.Group(); gg.visible=false;
  for(const [col,lo,hi] of [[0xe0251b,0,NRED],[0x2440e0,NRED,NPT]]){
    const n=hi-lo, arr=new Float32Array(n*NL*3);
    let k=0;
    for(let i=lo;i<hi;i++) for(let l=0;l<NL;l++){
      const p=pos[s][l][i]; arr[k++]=p.x; arr[k++]=p.y; arr[k++]=p.z;
    }
    const geo=new THREE.BufferGeometry();
    geo.setAttribute('position',new THREE.BufferAttribute(arr,3));
    gg.add(new THREE.Points(geo,new THREE.PointsMaterial({color:col,size:0.05,transparent:true,opacity:0.14,depthWrite:false})));
  }
  scene.add(gg); ghostGroups.push(gg);
}
function applyGhosts(){
  const on=document.getElementById('chkGhosts').checked;
  ghostGroups.forEach((g,s)=>{ g.visible=on&&s!==curStage; });
}

// ---------- trajectories ----------
const trajs=[], trajMats=[];
const _m=new THREE.Vector3();
function trajPoints(s,gap,i){
  const p0=pos[s][gap][i], p1=pos[s][gap+1][i];
  _m.copy(p0).add(p1).multiplyScalar(0.5);
  const bow=(i>=NRED)?0.45*(s/3)*((gap+1)/(NL-1)):0.05*(s/3);
  _m.x+=bow;
  return new THREE.QuadraticBezierCurve3(p0.clone(),_m.clone(),p1.clone()).getPoints(8);
}
for(let i=0;i<NPT;i++){
  trajs.push([]); trajMats.push([]);
  for(let g=0;g<NL-1;g++){
    const mat=new THREE.LineDashedMaterial({color:i<NRED?0xe0251b:0x2440e0,dashSize:0.07,gapSize:0.05,transparent:true,opacity:0.45});
    const ln=new THREE.Line(new THREE.BufferGeometry().setFromPoints(trajPoints(0,g,i)),mat);
    ln.computeLineDistances(); scene.add(ln);
    trajs[i].push(ln); trajMats[i].push(mat);
  }
}

// ---------- active plane highlight ----------
const hl=new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(
  [[-HALF-0.08,-HALF-0.08],[HALF+0.08,-HALF-0.08],[HALF+0.08,HALF+0.08],[-HALF-0.08,HALF+0.08]]
  .map(([x,z])=>new THREE.Vector3(x,0,z))),
  new THREE.LineBasicMaterial({color:0x00a651}));
hl.visible=false; scene.add(hl);

// ---------- legend ----------
const legendX=-3.4, legendNames=['linear','relu','linear','relu','linear','softmax'];
for(let k=0;k<6;k++){
  const y0=planeY(k)+0.18, y1=planeY(k+1)-0.15;
  scene.add(new THREE.ArrowHelper(new THREE.Vector3(0,1,0),new THREE.Vector3(legendX,y0,0),y1-y0,0x111111,0.14,0.09));
  const e=addLabel(legendNames[k],new THREE.Vector3(legendX,(y0+y1)/2,0),{offset:[-34,0],background:'#ffffff'});
  e.div.style.border='1px solid #333'; e.div.style.fontSize='11px';
}
addLabel('architecture',new THREE.Vector3(legendX,-0.55,0),{offset:[-34,0],fontSize:'11px',color:'#555'});

// ---------- training iteration arrow ----------
{
  const y=-1.1;
  const shaft=new THREE.Mesh(new THREE.CylinderGeometry(0.02,0.02,7.4,8).rotateZ(Math.PI/2),
    new THREE.MeshBasicMaterial({color:0x111111}));
  shaft.position.set(1.4,y,0); scene.add(shaft);
  const head=new THREE.Mesh(new THREE.ConeGeometry(0.09,0.28,10).rotateZ(-Math.PI/2),
    new THREE.MeshBasicMaterial({color:0x111111}));
  head.position.set(5.2,y,0); scene.add(head);
  addLabel('<b>Training iteration</b>',new THREE.Vector3(-1.4,y,0),{offset:[0,18],fontSize:'14px'});
  addLabel('···',new THREE.Vector3(2.1,y,0),{offset:[0,4]});
  addLabel('···',new THREE.Vector3(3.7,y,0),{offset:[0,4]});
}

// ---------- camera ----------
setCameraView({projection:'orthographic',axisScreenAngles:{x:30,z:30},rollDeg:0,heightFraction:0.75,target:[0.6,3.0,0]});

// ---------- state ----------
let curStage=0, fwdState=0, hoverId=-1;
const fwdNames=['idle','linear₁','relu₁','linear₂','relu₂','linear₃','softmax'];
const stageNames=['iteration 0 (untrained)','iteration 1','iteration 2','iteration 3 (trained)'];

function baseTrajOpacity(i,g){ return (fwdState===0||g===fwdState-1)?0.5:0.07; }

function applyFwd(){
  hl.visible=fwdState>0;
  if(fwdState>0) hl.position.y=planeY(fwdState);
  for(let l=0;l<NL;l++) planeEdgeMats[l].opacity=(fwdState===0||l===fwdState)?0.95:0.18;
  for(let g=0;g<NL-1;g++) prismMats[g].opacity=(fwdState===0||g===fwdState-1)?0.4:0.1;
  for(let i=0;i<NPT;i++){
    for(let g=0;g<NL-1;g++) trajMats[i][g].opacity=(i===hoverId)?1:baseTrajOpacity(i,g);
    markerMats[i].opacity=0.95;
  }
  document.getElementById('fwdStateLbl').textContent='forward pass: '+fwdNames[fwdState];
}

function applyStage(s){
  curStage=s;
  for(let i=0;i<NPT;i++){
    for(let l=0;l<NL;l++) markers[i][l].position.copy(pos[s][l][i]);
    for(let g=0;g<NL-1;g++){
      trajs[i][g].geometry.dispose();
      trajs[i][g].geometry=new THREE.BufferGeometry().setFromPoints(trajPoints(s,g,i));
      trajs[i][g].computeLineDistances();
    }
  }
  applyGhosts();
  applyFwd();
}

// ---------- UI wiring ----------
document.getElementById('trainIter').addEventListener('input',e=>{
  const s=+e.target.value;
  document.getElementById('trainIterVal').textContent=stageNames[s];
  applyStage(s);
});
document.getElementById('btnFwdStep').addEventListener('click',()=>{fwdState=(fwdState+1)%7;applyFwd();});
document.getElementById('btnFwdReset').addEventListener('click',()=>{fwdState=0;applyFwd();});
document.getElementById('chkGhosts').addEventListener('change',applyGhosts);

// ---------- hover trace ----------
for(let i=0;i<NPT;i++) registerInteractive(markers[i][3],{
  tooltip:'datapoint '+(i<NRED?'red ':'blue ')+((i%NRED)+1),
  title:'Trajectory trace',
  body:'This datapoint keeps its identity through every layer. Its dashed path shows how the forward pass reshapes its position until it lands in the red or blue bundle at the softmax plane.'
});
const _rc=new THREE.Raycaster(), _pv=new THREE.Vector2();
const _allMarkers=[]; for(let i=0;i<NPT;i++) for(let l=0;l<NL;l++) _allMarkers.push(markers[i][l]);
canvas.addEventListener('pointermove',(ev)=>{
  const r=canvas.getBoundingClientRect();
  _pv.x=((ev.clientX-r.left)/r.width)*2-1; _pv.y=-((ev.clientY-r.top)/r.height)*2+1;
  _rc.setFromCamera(_pv,camera);
  const h=_rc.intersectObjects(_allMarkers,false)[0];
  const id=h?h.object.userData.pointId:-1;
  if(id!==hoverId){
    hoverId=id;
    applyFwd();
  }
});
canvas.addEventListener('pointerleave',()=>{ hoverId=-1; applyFwd(); });

// ---------- demo steps ----------
function goToStep(st){
  const s=st.trainIter;
  fwdState=st.forwardPass==='idle'?0:({linear1:1,relu1:2,linear2:3,relu2:4,linear3:5,softmax:6})[st.forwardPass];
  document.getElementById('trainIter').value=s;
  document.getElementById('trainIterVal').textContent=stageNames[s];
  applyStage(s);
}
document.getElementById('demo0').addEventListener('click',()=>goToStep({trainIter:0,forwardPass:'idle'}));
document.getElementById('demo1').addEventListener('click',()=>goToStep({trainIter:2,forwardPass:'relu2'}));
document.getElementById('demo2').addEventListener('click',()=>goToStep({trainIter:3,forwardPass:'softmax'}));

applyStage(0);
// @FIGURE_CODE_END

